    imageHint: "Oslo fortress stone walls",
    descriptionAdvanced: {
      de: "Die Festung Akershus, majestätisch am Ufer des Oslofjords gelegen, ist eine der bedeutendsten historischen Verteidigungsanlagen Norwegens. Ihr Bau begann unter König Håkon V. Magnusson in den späten 1290er Jahren, um die wachsende Stadt Oslo vor Angriffen zu schützen. Im Laufe der Jahrhunderte widerstand die Festung zahlreichen Belagerungen, vor allem durch schwedische Truppen, und wurde nie durch kriegerische Gewalt eingenommen. Unter König Christian IV. wurde die mittelalterliche Burg im 17. Jahrhundert zu einem prachtvollen Renaissanceschloss umgebaut, das als königliche Residenz diente. Während der deutschen Besatzung im Zweiten Weltkrieg wurde die Anlage als Gefängnis und Hinrichtungsstätte genutzt, woran heute das nationale Widerstandsmuseum auf dem Gelände erinnert. In der Schlosskirche befindet sich die königliche Grabkapelle, in der mehrere norwegische Monarchen der Neuzeit ihre letzte Ruhestätte gefunden haben. Heute beherbergt das weitläufige Gelände das Verteidigungsministerium, dient aber auch als beliebtes Erholungsgebiet und Veranstaltungsort für staatliche Zeremonien.",
      hu: "Az Akershus erőd, amely az Oslo-fjord partján magasodik, Norvégia egyik legfontosabb történelmi védműve és a főváros szimbóluma. Az építkezést V. Haakon király kezdte meg az 1290-es évek végén, hogy megvédje a fejlődő várost a külső támadásoktól. Az évszázadok során az erőd számos ostromot élt túl, különösen a svéd seregek részéről, és soha nem tudták fegyveres úton elfoglalni. A 17. században IV. Keresztély király modernizálta az építményt, és a középkori várat elegáns reneszánsz kastéllyá alakíttatta át, amely királyi rezidenciaként is szolgált. A második világháború alatti német megszállás idején az erődöt börtönként és kivégzőhelyként használták, amire ma a területen található Nemzeti Ellenállási Múzeum emlékeztet. A várkápolnában található a királyi mauzóleum, ahol a modern kori norvég uralkodók nyugszanak. Napjainkban az erőd a Védelmi Minisztériumnak ad otthont, emellett népszerű kirándulóhely és az állami ünnepségek kiemelt helyszíne.",
      ro: "Cetatea Akershus, situată strategic pe malul fiordului Oslo, este una dintre cele mai importante fortificații istorice din Norvegia. Construcția sa a fost inițiată de regele Håkon al V-lea Magnusson la sfârșitul anilor 1290 pentru a proteja orașul Oslo împotriva atacurilor maritime și terestre. De-a lungul secolelor, fortăreața a rezistat la numeroase asedii, în special din partea forțelor suedeze, nefiind niciodată cucerită prin luptă. În secolul al XVII-lea, sub domnia lui Christian al IV-lea, castelul medieval a fost transformat într-o reședință regală în stil renascentist, căpătând un aspect mult mai elegant. În timpul ocupației germane din Al Doilea Război Mondial, complexul a servit drept închisoare și loc de execuție pentru membrii rezistenței, fapt comemorat astăzi de Muzeul Rezistenței aflat în incintă. În capela castelului se află Necropola Regală, unde sunt înmormântați monarhii norvegieni ai epocii moderne. Astăzi, cetatea găzduiește sediul Ministerului Apărării, fiind totodată un parc public apreciat și locul de desfășurare a ceremoniilor de stat.",
      en: "Akershus Fortress, overlooking the Oslo Fjord, is one of Norway's most significant historical landmarks and a symbol of national resilience. Construction began in the late 1290s under King Håkon V Magnusson to defend the capital against emerging naval and land-based threats. Throughout its long history, the fortress withstood numerous sieges, primarily by Swedish forces, and was never captured in combat. During the 17th century, King Christian IV modernized the defenses and converted the medieval castle into a grand Renaissance palace, which served as a royal residence. The site took on a darker role during the German occupation in World War II, serving as a prison and execution ground for the resistance, a period now chronicled in the on-site Norwegian Resistance Museum. The Royal Mausoleum, located within the castle church, is the final resting place of several modern Norwegian monarchs. Today, the fortress remains an active military site housing the Ministry of Defence, while also serving as a popular public park and a venue for official state functions.",
      es: "La Fortaleza de Akershus en Oslo fue construida alrededor de 1299 y sirvió como residencia real y bastión militar. Sobrevivió a varios asedios y fue reconstruida en estilo renacentista en el siglo XVII. Hoy alberga el Museo de la Resistencia Noruega y el Ministerio de Defensa.",
      pt: "A Fortaleza de Akershus em Oslo foi construída por volta de 1299 e serviu como residência real e bastião militar. Sobreviveu a vários cercos e foi reconstruída em estilo renascentista no século XVII. Hoje abriga o Museu da Resistência Norueguesa e o Ministério da Defesa.",
      fr: "La forteresse d'Akershus à Oslo a été construite vers 1299 et a servi de résidence royale et de bastion militaire. Elle a survécu à plusieurs sièges et a été transformée en style Renaissance au XVIIe siècle. Aujourd'hui, elle abrite le musée de la Résistance norvégienne et le ministère de la Défense.",
    },
    factsAdvanced: {
      de: ["Der Bau der Festung begann etwa im Jahr 1299 unter König Håkon V.", "Akershus wurde in seiner gesamten Geschichte nie durch eine Belagerung eingenommen.", "König Christian IV. baute die Burg zwischen 1588 und 1648 zum Renaissanceschloss um.", "In der königlichen Grabkapelle ruhen unter anderem König Haakon VII. und Olav V.", "Das nationale Widerstandsmuseum dokumentiert die Besatzung von 1940 bis 1945.", "Jeden Tag um 13:30 Uhr findet auf dem Gelände die Wachablösung statt."],
      hu: ["Az erőd építése 1299 körül kezdődött V. Haakon király uralkodása alatt.", "Akershus története során soha nem esett el ostrom következtében.", "IV. Keresztély király 1588 és 1648 között alakíttatta át reneszánsz stílusúvá.", "A királyi mauzóleumban nyugszik többek között VII. Haakon és V. Olav király.", "A területen működő ellenállási múzeum az 1940-45 közötti megszállást mutatja be.", "Az erődben minden nap 13:30-kor látványos őrségváltást tartanak."],
      ro: ["Construcția cetății a început în jurul anului 1299 sub regele Håkon al V-lea.", "Akershus nu a fost niciodată cucerită prin forță militară în timpul unui asediu.", "Regele Christian al IV-lea a transformat cetatea în castel renascentist în secolul XVII.", "Necropola Regală adăpostește rămășițele regilor Haakon al VII-lea și Olav al V-lea.", "Muzeul Rezistenței din incintă documentează perioada ocupației dintre 1940 și 1945.", "Schimbarea gărzii are loc zilnic în incinta cetății la ora 13:30."],
      en: ["Construction of the fortress was initiated around 1299 by King Håkon V.", "Akershus has the distinction of never being successfully taken by siege.", "King Christian IV remodeled the medieval castle into a Renaissance palace after 1588.", "The Royal Mausoleum contains the tombs of King Haakon VII and King Olav V.", "The Norwegian Resistance Museum on the site covers the occupation from 1940 to 1945.", "The Changing of the Guard takes place daily at 1:30 PM within the fortress grounds."],
      es: ["Inicio de la construcción hacia 1299", "Superficie: 0,12 km²", "Torre más alta: 25 m", "Espesor de los muros: hasta 4 m", "Visitantes del museo: aprox. 200.000 anuales", "Abierta al público desde 1897"],
      pt: ["Início da construção por volta de 1299", "Área: 0,12 km²", "Torre mais alta: 25 m", "Espessura da parede: até 4 m", "Visitantes do museu: cerca de 200.000 anualmente", "Aberto ao público desde 1897"],
      fr: ["Début de la construction vers 1299", "Superficie : 0,12 km²", "Tour la plus haute : 25 m", "Épaisseur des murs : jusqu'à 4 m", "Visiteurs des musées : env. 200 000 par an", "Ouvert au public depuis 1897"],
    },
