      es: ["Fundado en el siglo XIX", "Centro del comercio de pescado", "Muchos edificios originales conservados", "Monumento histórico-cultural"],
      pt: ["Fundado no século XIX", "Centro do comércio de peixe", "Muitos edifícios originais preservados", "Monumento histórico-cultural"],
