      fr: ["Peuplement depuis le XVe siècle", "Habitants : env. 500", "Nombre d'îles : 5", "Production de morue séchée : env. 1 000 tonnes par an", "Nombre de ponts : 7", "Stade de Henningsvær (terrain de football) construit en 2005"],
