    imageHint: "Mosjoen Sjogata historic street",
    descriptionAdvanced: {
      de: "Sjøgata in Mosjøen ist eine der am besten erhaltenen historischen Holzhausstraßen in Nordnorwegen und stammt überwiegend aus dem 19. Jahrhundert. Das Viertel entstand während der Blütezeit des Holzhandels und der Schifffahrt, als Mosjøen ein wichtiger Handelsplatz für die umliegenden Täler und die Küste war. Die Straße umfasst etwa 100 Gebäude, darunter alte Lagerhäuser (Brygger), Werkstätten, Wohnhäuser und kleine Geschäfte, die direkt am Ufer des Vefsnfjords liegen. In den 1970er Jahren gab es Pläne, das Viertel abzureißen, doch engagierte Bürger retteten die historische Bausubstanz, was heute als Meilenstein des norwegischen Denkmalschutzes gilt. Jedes Haus in Sjøgata hat seine eigene Geschichte und ist oft in traditionellen Farben wie Ocker, Rot oder Weiß gestrichen. Heute beherbergt das Viertel Ateliers, gemütliche Cafés und Gästehäuser, die eine authentische Atmosphäre vergangener Zeiten vermitteln. Sjøgata ist nicht nur ein Architekturdenkmal, sondern auch ein lebendiger Treffpunkt, an dem Kulturfestivals wie das 'Byfest' stattfinden, die die lokale Identität feiern.",
      hu: "A mosjøeni Sjøgata Észak-Norvégia egyik legjobban megőrzött történelmi faházas utcája, amely túlnyomórészt a 19. századból származik. A negyed a fakereskedelem és a hajózás fénykorában alakult ki, amikor Mosjøen a környező völgyek és a tengerpart fontos kereskedelmi központja volt. Az utca körülbelül 100 épületet foglal magában, köztük régi raktárakat (brygger), műhelyeket, lakóházakat és kis üzleteket, amelyek közvetlenül a Vefsn-fjord partján találhatók. Az 1970-es években tervek születtek a negyed lebontására, de az elkötelezett polgárok megmentették a történelmi épületeket, ami ma a norvég műemlékvédelem mérföldkövének számít. Sjøgata minden házának saját története van, és gyakran hagyományos színekre, például okkersárgára, vörösre vagy fehérre festették őket. Ma a negyed műtermeknek, hangulatos kávézóknak és vendégházaknak ad otthont, amelyek a múlt idők hiteles hangulatát közvetítik. Sjøgata nemcsak építészeti emlék, hanem életteli találkozóhely is, ahol olyan kulturális fesztiválokat tartanak, mint a helyi identitást ünneplő 'Byfest'.",
      ro: "Sjøgata din Mosjøen este una dintre cele mai bine conservate străzi istorice cu case din lemn din nordul Norvegiei, datând predominant din secolul al XIX-lea. Cartierul s-a dezvoltat în timpul perioadei de glorie a comerțului cu lemn și a navigației, când Mosjøen era un loc comercial important pentru văile învecinate și coastă. Strada cuprinde aproximativ 100 de clădiri, inclusiv depozite vechi (brygger), ateliere, case de locuit și mici magazine, situate direct pe malul Vefsnfjord. În anii 1970 au existat planuri de demolare a cartierului, dar cetățenii dedicați au salvat structura istorică, ceea ce este considerat astăzi un punct de referință al protecției monumentelor din Norvegia. Fiecare casă din Sjøgata are propria istorie și este adesea vopsită în culori tradiționale precum ocru, roșu sau alb. Astăzi, cartierul găzduiește ateliere, cafenele primitoare și pensiuni care transmit o atmosferă autentică a vremurilor trecute. Sjøgata nu este doar un monument de arhitectură, ci și un loc de întâlnire plin de viață, unde au loc festivaluri culturale precum 'Byfest', care celebrează identitatea locală.",
      en: "Sjøgata in Mosjøen is one of Northern Norway's best-preserved historical wooden house streets, predominantly dating from the 19th century. The district developed during the heyday of timber trade and shipping, when Mosjøen was an important trading post for the surrounding valleys and the coast. The street comprises about 100 buildings, including old warehouses (brygger), workshops, residential houses, and small shops located directly on the banks of the Vefsnfjord. In the 1970s, there were plans to demolish the district, but dedicated citizens saved the historical buildings, which is now considered a milestone in Norwegian heritage protection. Each house in Sjøgata has its own story and is often painted in traditional colors like ochre, red, or white. Today, the district houses studios, cozy cafes, and guesthouses that convey an authentic atmosphere of bygone times. Sjøgata is not only an architectural monument but also a vibrant meeting place where cultural festivals like 'Byfest' are held, celebrating local identity.",
      es: "Sjøgata es la histórica calle principal de Mosjøen, en la provincia de Nordland, Noruega. Es conocida por sus casas de madera del siglo XIX bien conservadas, situadas a lo largo del río Vefsna. Sjøgata fue el centro económico de la ciudad durante el auge de la madera. Muchos edificios albergan hoy galerías, cafeterías y tiendas. La calle forma parte del área protegida de interés cultural. La casa más antigua data de 1836. Mosjøen fue fundada en 1874. Sjøgata fue un importante lugar de comercio regional. Las casas de madera suelen estar pintadas de rojo o blanco. Un incendio en 1893 destruyó partes de la calle, pero muchas casas fueron reconstruidas.",
      pt: "Sjøgata é a histórica rua principal de Mosjøen, na província de Nordland, Noruega. É conhecida pelas suas casas de madeira do século XIX bem preservadas ao longo do rio Vefsna. Sjøgata era o centro económico da cidade durante o auge da exploração de madeira. Muitos edifícios são hoje galerias, cafés e lojas. A rua faz parte da área protegida de património cultural. A casa mais antiga data de 1836. A própria Mosjøen foi fundada em 1874. Sjøgata era um importante centro comercial regional. As casas de madeira são tradicionalmente pintadas de vermelho ou branco. Um incêndio em 1893 destruiu partes da rua, mas muitas casas foram reconstruídas.",
      fr: "Sjøgata est la rue principale historique de Mosjøen, dans la province de Nordland, en Norvège. Elle est réputée pour ses maisons en bois du XIXe siècle bien conservées, situées le long de la rivière Vefsna. Sjøgata était le centre économique de la ville pendant l'essor de l'industrie du bois. De nombreux bâtiments abritent aujourd'hui des galeries, des cafés et des boutiques. La rue fait partie d'une zone de protection du patrimoine culturel. La maison la plus ancienne date de 1836. Mosjøen elle-même a été fondée en 1874. Sjøgata était un centre commercial important pour la région. Les maisons en bois sont traditionnellement peintes en rouge ou en blanc. Un incendie en 1893 a détruit une partie de la rue, mais de nombreuses maisons ont été reconstruites.",
    },
