      en: ["The street consists of over 100 protected wooden buildings.", "The oldest building in the district dates from 1794.", "Mosjøen received trading post (ladested) status in 1875.", "The rescue from demolition was achieved by a citizens' initiative around 1970.", "The district is located directly at the mouth of the Vefsna river.", "Sjøgata was awarded the prestigious Olavsrosa for cultural heritage."],
