      pt: ["Casa mais antiga: 1836.", "Mosjøen fundada em: 1874.", "Comprimento da Sjøgata: aprox. 500 m.", "Número de casas de madeira históricas: mais de 80.", "Incêndio de 1893 destruiu 20 casas.", "Altitude acima do nível do mar: 10 m."],
